// MetaDataFinder (MDF) core module: shared state and metadata-domain logic.
// Load this file first.

// PURPOSE
// -------
// MDF modules let the user select a local folder, recursively scans it for JSON
// files, keeps only JSON objects generated by MetaDataMaker, builds a list of
// filterable metadata paths, and evaluates user-built boolean queries.
//
// BROWSER SECURITY NOTE
// ---------------------
// Browsers do not expose absolute filesystem paths. Therefore, MDF displays
// paths relative to the user-selected folder. With showDirectoryPicker()
// the selected folder name is prepended. With the fallback file input, the
// browser-provided webkitRelativePath is used when available.

// -----------------------------------------------------------------------------
// IIFE: Immediately Invoked Function Expression
// -----------------------------------------------------------------------------
// Everything is wrapped in an anonymous function that is executed immediately.
// This creates a private scope for constants, state variables, and helper
// functions. Only the explicitly exported functions at the bottom become
// visible as window.MDMFinder.
// Without this wrapper, top-level variables/functions could become global and
// potentially collide with theme scripts or future MDM scripts loaded on the
// same page.

(function (global) {
    "use strict"; // to catch common mistakes early

    const MDMFinder = global.MDMFinder || (global.MDMFinder = {});

    const constants = Object.freeze({
        MDM_GENERATOR: "MetaDataMaker",
        ANY_KEY: "[ ANY ]",
        STATUS_UPDATE_INTERVAL: 50,
        COMPARISON_OPERATORS: Object.freeze([
            { value: "=", label: "=" },
            { value: "!=", label: "≠" },
            { value: ">", label: ">" },
            { value: "<", label: "<" },
            { value: ">=", label: "≥" },
            { value: "<=", label: "≤" }
        ])
    });

    // All mutable data used by the Finder is kept in this one object.
    const state = {
        selectedRootLabel: "",  // Label for the selected target folder.
        scannedEntries: 0,      // Number of entries (files or dirs) scanned.
        jsonFilesSeen: 0,       // Number of .json files actually inspected.
        mdmFiles: [],           // Accepted MDM JSON files (1).
        parseErrors: [],        // Collect errors and keep scanning.
        skippedEntries: [],     // Entries skipped because access not allowed.
        keySet: new Set(),      // All filterable metadata paths found (2).
        queryElements: [],      // User-built query as a list of row objects.
        nextQueryId: 1,         // Unique incremental identifier for query rows.
        searchCancelRequested: false,    // Flag checked during scanning.
        isSearching: false      // True while a folder scan is running.
    };

    // (1): Accepted MDM JSON files. Each item of the array is an objects with
    //      this shape:
    // {
    //   name: file name only,
    //   path: selected-folder-relative path,
    //   size: file size in bytes,
    //   lastModified: browser-provided timestamp,
    //   metadata: parsed JSON object
    // }
    //
    // (2): Set of all filterable metadata paths found in accepted MDM JSON
    //      files. A Set automatically avoids duplicates.

    // The marker used to recognize JSON files produced by MetaDataMaker.
    // A JSON file is accepted only if metadata.generated_by === MDM_GENERATOR.
    const MDM_GENERATOR = constants.MDM_GENERATOR;

    // The special pseudo-key to search the entered value across all discovered
    // filterable metadata paths.
    const ANY_KEY = constants.ANY_KEY;
    
    // -------------------------------------------------------------------------
    // Helper functions
    // -------------------------------------------------------------------------

    // Give the browser a chance to repaint and respond to clicks during long
    // asynchronous scans. Without this, very large scans may make the UI feel
    // frozen even though the code is running.
    function yieldToBrowser() {
        return new Promise(resolve => window.setTimeout(resolve, 0));
    }

    // Case-insensitive check for JSON filenames.
    function isJsonFileName(fileName) {
        return String(fileName || "").toLowerCase().endsWith(".json");
    }

    // Format numbers using the user's locale.
    // E.g.: 12000 -> 12,000 or 12.000 depending on locale.
    function formatInteger(value) {
        return Number(value || 0).toLocaleString();
    }

    // Test whether a parsed JSON value is an MDM metadata object.
    // Only plain objects are accepted; arrays/null/primitives are rejected.
    function isMdmMetadata(value) {
        return value !== null &&
            typeof value === "object" &&
            !Array.isArray(value) &&
            value.generated_by === MDM_GENERATOR;
    }

    // Convert different error-like values into a readable string.
    function readableError(err) {
        if (!err) return "unknown error";
        return err.message || err.name || String(err);
    }

    // -------------------------------------------------------------------------
    // Metadata path collection and lookup
    // -------------------------------------------------------------------------

    // Recursively inspect a value and add every useful metadata path to keySet.
    // `path` is the dot-separated path accumulated so far.
    //
    // Array convention:
    // If an array is found at, e.g., "events", the array itself is added as
    // "events" and child object paths use "events[]", for example:
    //
    //   events[].time
    //   events[].stimulus
    function collectFilterablePaths(value, path, keySet) {
        if (value === undefined) return;

        // Primitive or null: the current path is directly filterable.
        if (value === null || typeof value !== "object") {
            if (path) keySet.add(path);
            return;
        }

        // Array: add the array path itself, then inspect each item using [] to
        // mark that the path traverses array elements.
        if (Array.isArray(value)) {
            if (path) keySet.add(path);
            const arrayPath = path ? path + "[]" : "[]";

            value.forEach(item => {
                collectFilterablePaths(item, arrayPath, keySet);
            });
            return;
        }

        // Some MDM fields are objects like:
        //
        //   { "value": 3.2, "unit": "MΩ" }
        //
        // For these, the parent path is also useful because a user may want to
        // filter by "patch_clamp.seal_resistance" rather than specifically by
        // "patch_clamp.seal_resistance.value".
        if (path && Object.prototype.hasOwnProperty.call(value, "value")) {
            keySet.add(path);
        }

        // Recurse into object properties.
        Object.keys(value).forEach(key => {
            const childPath = path ? path + "." + key : key;
            collectFilterablePaths(value[key], childPath, keySet);
        });
    }

    // Retrieve all values matching a dot-separated metadata path. Example:
    //
    //   getValuesAtPath(metadata, "cell_cultures.cell_type")
    //
    // returns an array, not a single value, since paths can pass through arrays.
    function getValuesAtPath(root, path) {
        if (!path) return [root];

        const segments = path.split(".");
        let contexts = [root];

        segments.forEach(segment => {
            const expandArray = segment.endsWith("[]");
            const key = expandArray ? segment.slice(0, -2) : segment;
            const nextContexts = [];

            contexts.forEach(context => {
                if (context === null || context === undefined) return;

                if (Array.isArray(context)) {
                    context.forEach(item => {
                        addSegmentValue(item, key, expandArray, nextContexts);
                    });
                } else {
                    addSegmentValue(context, key, expandArray, nextContexts);
                }
            });

            contexts = nextContexts;
        });

        return contexts.filter(value => value !== undefined);
    }

    // Helper used by getValuesAtPath() for one path segment.
    // If expandArray is true and the extracted value is an array, each array
    // item is pushed separately to output.
    function addSegmentValue(context, key, expandArray, output) {
        if (context === null || context === undefined) return;

        let value;

        if (key === "") {
            value = context;
        } else if (typeof context === "object" && key in context) {
            value = context[key];
        } else {
            return;
        }

        if (expandArray && Array.isArray(value)) {
            value.forEach(item => output.push(item));
        } else {
            output.push(value);
        }
    }

    // Make the universal "any" key case-insensitive.
    function isAnyKeyPath(keyPath) {
        return String(keyPath || "").trim().toLowerCase() === ANY_KEY.toLowerCase();
    }

    // Return all filterable values as an array.
    function getAllFilterableValues(metadata) {
        const values = [];

        Array.from(state.keySet).forEach(keyPath => {
            getValuesAtPath(metadata, keyPath).forEach(value => {
                values.push(value);
            });
        });

        return values;
    }

    // Convert any metadata value into a list of simple comparable values.
    // This lets the filter match against:
    //   - primitive values directly
    //   - every item in an array
    //   - object.value
    //   - object.unit
    //   - "value unit"
    //   - JSON string representation of an object
    function extractComparableValues(value, output = []) {
        if (value === undefined) return output;

        if (value === null) {
            output.push(null);
            return output;
        }

        if (Array.isArray(value)) {
            value.forEach(item => extractComparableValues(item, output));
            return output;
        }

        if (typeof value === "object") {
            const hasValue = Object.prototype.hasOwnProperty.call(value, "value");
            const hasUnit = Object.prototype.hasOwnProperty.call(value, "unit");

            if (hasValue) output.push(value.value);
            if (hasUnit) output.push(value.unit);
            if (hasValue && hasUnit) output.push(String(value.value) + " " + String(value.unit));

            try {
                output.push(JSON.stringify(value));
            } catch (err) {
                output.push(String(value));
            }
            return output;
        }

        output.push(value);
        return output;
    }

    // -------------------------------------------------------------------------
    // Filtering by query matching
    // -------------------------------------------------------------------------

    // Evaluate one Key-Value row against one metadata object. If the value
    // field is empty and comparator is "=", condition means: "this key exists".
    // If comparator is "!=", the key must exist and none of the values found at
    // this key path may match the user-entered value. Missing keys return false.
    // If comparator is >, <, >=, or <=, at least one value found at this key
    // path must be comparable as a pure number, a semantic version, or as an
    // ISO date.
    function evaluateKeyValue(metadata, keyPath, queryValue, comparator = "=") {
        const rawValues = isAnyKeyPath(keyPath)
            ? getAllFilterableValues(metadata)
            : getValuesAtPath(metadata, keyPath);

        // Important for "!=": a missing key should not match.
        // Without this rule, a query such as:
        //
        //   cell_cultures.cell_type != HEK
        //
        // would also return files with no cell_cultures.cell_type field at all,
        // which is usually not what a metadata search user expects.
        if (rawValues.length === 0) return false;

        const normalizedComparator = normalizeComparator(comparator);
        const query = String(queryValue || "").trim();

        // Empty value produce the "key exists" behavior only for equality.
        // Empty "!=" and relational comparisons are invalid and are normally
        // caught by compileQuery(), but this guard keeps evaluation safe too.
        if (query === "") {
            return normalizedComparator === "=" &&
                rawValues.some(value => value !== undefined);
        }

        if (normalizedComparator === "!=") {
            // Equality means "at least one value at this path matches".
            // Not-equal therefore means the key exists and no value at this path
            // matches. This is safer than checking whether some value differs,
            // because paths expanded through arrays can produce multiple values.
            return !rawValues.some(value => valueMatchesEqualityQuery(value, query));
        }

        return rawValues.some(value => {
            return valueMatchesQuery(value, query, normalizedComparator);
        });
    }

    // Compare one raw metadata value against the text typed by the user.
    //
    // Equality matching rules:
    //   - strings: case-insensitive substring match
    //   - booleans: true/false are matched as booleans when possible
    //   - numbers: exact numeric match when the query is numeric
    //   - objects: compare against value, unit, "value unit", and JSON string
    //
    // "!=" is handled here as the negation of equality for one raw value.
    // evaluateKeyValue() applies the path-level rule that no value at the
    // selected path may match.
    function valueMatchesQuery(rawValue, query, comparator = "=") {
        const normalizedComparator = normalizeComparator(comparator);

        if (normalizedComparator === "!=") {
            return !valueMatchesEqualityQuery(rawValue, query);
        }

        if (isRelationalComparator(normalizedComparator)) {
            return valueMatchesRelationalQuery(rawValue, query, normalizedComparator);
        }

        return valueMatchesEqualityQuery(rawValue, query);
    }

    // Equality-matching logic.
    function valueMatchesEqualityQuery(rawValue, query) {
        const queryLower = query.toLowerCase();
        const queryBoolean = parseBoolean(query);
        const queryNumber = parseNumberStrict(query);
        const values = extractComparableValues(rawValue);

        return values.some(value => {
            if (value === null) {
                return queryLower === "null";
            }

            if (typeof value === "boolean") {
                return queryBoolean === null
                    ? String(value).toLowerCase().includes(queryLower)
                    : value === queryBoolean;
            }

            if (typeof value === "number") {
                return queryNumber === null
                    ? String(value).toLowerCase().includes(queryLower)
                    : value === queryNumber;
            }

            return String(value).toLowerCase().includes(queryLower);
        });
    }

    // Relational comparison for >, <, >=, <=.
    // extractComparableValues() can return several candidates for one raw field.
    // For example, an MDM unit object may produce:
    //
    //   3.2
    //   "MΩ"
    //   "3.2 MΩ"
    //   "{...}"
    //
    // This function tries each candidate and succeeds if at least one candidate
    // can be compared with the query as the same scalar type.
    function valueMatchesRelationalQuery(rawValue, query, comparator) {
        const queryComparable = parseComparableScalar(query);
        if (queryComparable === null) return false;

        const values = extractComparableValues(rawValue);

        return values.some(value => {
            const valueComparable = parseComparableScalar(value);
            if (valueComparable === null) return false;

            // Do not compare a date against a number, a number against a
            // version, a version against a date, etc.
            if (valueComparable.type !== queryComparable.type) return false;

            if (valueComparable.type === "semver") {
                return compareSemanticVersions(
                    valueComparable.value,
                    queryComparable.value,
                    comparator
                );
            }

            return compareScalars(
                valueComparable.value,
                queryComparable.value,
                comparator
            );
        });
    }

    // Only "=" allows an empty value, where empty means "key exists".
    // All other comparison operators need an explicit value.
    function requiresExplicitComparisonValue(comparator) {
        return normalizeComparator(comparator) !== "=";
    }

    // Convert different textual variants into the internal comparison operators.
    // This lets the code tolerate either >= or ≥, either <= or ≤, and either
    // != or ≠.
    function normalizeComparator(comparator) {
        const value = String(comparator || "=").trim();

        if (value === "!=" || value === "≠") return "!=";
        if (value === ">") return ">";
        if (value === "<") return "<";
        if (value === ">=" || value === "≥") return ">=";
        if (value === "<=" || value === "≤") return "<=";

        return "=";
    }

    // True only for operators that require numeric/date comparison.
    function isRelationalComparator(comparator) {
        const normalized = normalizeComparator(comparator);

        return normalized === ">" ||
            normalized === "<" ||
            normalized === ">=" ||
            normalized === "<=";
    }

    // Compare two already-parsed scalar values.
    function compareScalars(left, right, comparator) {
        switch (normalizeComparator(comparator)) {
            case ">":
                return left > right;
            case "<":
                return left < right;
            case ">=":
                return left >= right;
            case "<=":
                return left <= right;
            default:
                return left === right;
        }
    }

    // Compare two already-parsed semantic versions.
    function compareSemanticVersions(left, right, comparator) {
        const comparison = compareSemanticVersionTriplets(left, right);

        switch (normalizeComparator(comparator)) {
            case ">":
                return comparison > 0;
            case "<":
                return comparison < 0;
            case ">=":
                return comparison >= 0;
            case "<=":
                return comparison <= 0;
            default:
                return comparison === 0;
        }
    }

    function compareSemanticVersionTriplets(left, right) {
        for (let i = 0; i < 3; i += 1) {
            const leftPart = left[i];
            const rightPart = right[i];

            if (leftPart > rightPart) return 1;
            if (leftPart < rightPart) return -1;
        }

        return 0;
    }

    // Parse a raw value as either:
    //
    //   { type: "number", value: Number }
    //   { type: "date", value: milliseconds_since_epoch }
    //   { type: "semver", value: [Major, Minor, Patch] }
    //
    // Returns null if the value is not a pure number and not a strict ISO date.
    // This is the key guard that prevents >/< from affecting arbitrary strings.
    function parseComparableScalar(value) {
        if (value === null || value === undefined) return null;

        if (typeof value === "number") {
            return Number.isFinite(value)
                ? { type: "number", value }
                : null;
        }

        const text = String(value).trim();
        if (text === "") return null;

        const number = parseNumberStrict(text);
        if (number !== null) {
            return { type: "number", value: number };
        }

        const date = parseIsoDateStrict(text);
        if (date !== null) {
            return { type: "date", value: date };
        }

        const semanticVersion = parseSemanticVersionStrict(text);
        if (semanticVersion !== null) {
            return { type: "semver", value: semanticVersion };
        }

        return null;
    }

    // Parse a strict ISO date of the form YYYY-MM-DD.
    //
    // This matches the format produced by HTML <input type="date">,
    // which MDM uses for general.date.
    //
    // Invalid calendar dates, such as 2026-02-31, are rejected instead of being
    // silently normalized by Date.parse().
    function parseIsoDateStrict(text) {
        const match = String(text || "").trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
        if (!match) return null;

        const year = Number(match[1]);
        const month = Number(match[2]);
        const day = Number(match[3]);

        const milliseconds = Date.UTC(year, month - 1, day);
        const date = new Date(milliseconds);

        const valid =
            date.getUTCFullYear() === year &&
            date.getUTCMonth() === month - 1 &&
            date.getUTCDate() === day;

        return valid ? milliseconds : null;
    }

    // Parse a strict three-component semantic version of the form MAJOR.MINOR.PATCH
    function parseSemanticVersionStrict(text) {
        const match = String(text || "").trim().match(/^(\d+)\.(\d+)\.(\d+)$/);
        if (!match) return null;

        return [
            Number(match[1]),
            Number(match[2]),
            Number(match[3])
        ];
    }

    // Parse a text value as boolean only if it is exactly true or false.
    function parseBoolean(text) {
        const value = String(text || "").trim().toLowerCase();
        if (value === "true") return true;
        if (value === "false") return false;
        return null;
    }

    // Parse a text value as number only if the whole string is numeric.
    // This avoids treating a string like "3 mV" as number 3.
    function parseNumberStrict(text) {
        const trimmed = String(text || "").trim();
        if (trimmed === "") return null;
        if (!/^[-+]?\d+(\.\d+)?([eE][-+]?\d+)?$/.test(trimmed)) return null;

        const number = Number(trimmed);
        return Number.isFinite(number) ? number : null;
    }

    // -------------------------------------------------------------------------

    MDMFinder.core = Object.freeze({
        constants,
        state,
        yieldToBrowser,
        isJsonFileName,
        formatInteger,
        isMdmMetadata,
        readableError,
        collectFilterablePaths,
        getValuesAtPath,
        extractComparableValues,
        evaluateKeyValue,
        valueMatchesQuery,
        normalizeComparator,
        isRelationalComparator,
        requiresExplicitComparisonValue,
        parseComparableScalar,
        parseIsoDateStrict,
        parseSemanticVersionStrict,
        parseBoolean,
        parseNumberStrict
    });

})(window);
